// Package locales embeds the ICU MessageFormat catalogs shared by the server and the clients
// (ADR-0009). A namespace is a directory locales/<BCP47>/<namespace>/ of files in the FormatJS JSON
// shape, one per area of its keys (ADR-0081); en is the source locale, en-XA and ar-XB are
// pseudo-locales generated by tools/i18n. Only internal/i18n reads this package.
package locales

import "embed"

// FS holds the <locale>/<namespace>/ directories of the namespaces Go formats: every namespace but
// client*, which only the TypeScript clients read and whose pseudo-locales are not committed (ADR-0081).
// A directory pattern embeds the files of a new area without a change here; a new namespace Go formats
// needs its pattern, and TestFS fails until it has one.
//
//go:embed */server
var FS embed.FS
